const { mc, qcm, vf, glisser, entourer, ordre, relier, classer, b, lecon } = require('../dsl');
const original = { type: 'original', inspireDe: 'ENS Éducateur 2026 — système éducatif ivoirien' };
const annale2026 = { type: 'annale', organisme: 'ENS', annee: 2026, epreuve: 'Éducateur — Psychopédagogie (système éducatif ivoirien)', documentId: '6ae69a5411c325e41b45d4cc' };
const question = (module, i, notion, consigne, options, explication) => b.question(qcm({ code: `${module}-L${i}-Q1`, niveau: 1, notions: [notion], source: module === 'EDU-SEI' ? original : { type: 'original', inspireDe: 'ENS Éducateur : préparation psychopédagogique, complément au sujet 2026' }, consigne, options, bonne: 0, explication }));
const fiche = (module, i, niveau, notions, titre, corps, aRetenir) => ({ code: `${module}-E${String(i).padStart(2, '0')}`, niveau, notions, source: original, miniCours: mc(titre, corps, aRetenir) });
const edu = (...args) => fiche('EDU-SEI', ...args);

const systemeEducatif = {
  code: 'EDU-SEI', matiere: 'Psychopédagogie et système éducatif', titre: 'Le système éducatif ivoirien et l’éducateur',
  resume: 'Comprendre les parcours scolaires, l’obligation de scolarité, les acteurs, la vie scolaire et les enjeux d’orientation.',
  notions: [
    { code: 'STRUCTURE', libelle: 'Cycles et examens de l’enseignement général' },
    { code: 'OBLIGATOIRE', libelle: 'Scolarisation obligatoire et accès effectif' },
    { code: 'GOUVERNANCE', libelle: 'Acteurs et gouvernance scolaire' },
    { code: 'VIE-SCOLAIRE', libelle: 'Missions et suivi éducatif' },
    { code: 'CADRE', libelle: 'Règles, protection et responsabilité éducative' },
    { code: 'ORIENTATION', libelle: 'Enseignement technique, formation et insertion' },
    { code: 'ANALYSE', libelle: 'Construire une réponse sur le système éducatif' },
  ],
  lecons: [
    lecon('EDU-SEI-L1', 'Lire le parcours de l’enseignement général', 4, [
      b.texte('Nous allons situer un élève dans le **système éducatif**, ensemble organisé des formations, institutions et acteurs de l’éducation. Cela aide à comprendre les transitions et les besoins d’accompagnement.'),
      b.texte('Un **cycle** regroupe plusieurs années de formation. Une **classe** est une étape annuelle. L’enseignement **général** apporte une formation large ; d’autres parcours techniques et professionnels seront présentés plus loin.'),
      b.tableau(['Cycle', 'Étapes', 'Durée habituelle'], [['Préscolaire', 'Petite, moyenne, grande sections', '3 ans'], ['Primaire', 'CP1, CP2, CE1, CE2, CM1, CM2', '6 ans'], ['Secondaire premier cycle', '6e, 5e, 4e, 3e', '4 ans'], ['Secondaire second cycle', 'Seconde, première, terminale', '3 ans']]),
      b.exemple('Du primaire au collège', 'Après le CM2, l’entrée au premier cycle secondaire suit les règles d’admission et d’orientation applicables. Le changement de cadre et la multiplication des enseignants peuvent demander un accompagnement.'),
      b.tableau(['Fin de cycle', 'Examen repère'], [['CM2', 'CEPE : certificat d’études primaires élémentaires'], ['3e', 'BEPC : brevet d’études du premier cycle'], ['Terminale', 'Baccalauréat']]),
      b.piege('Les durées décrivent un parcours habituel, pas l’âge exact de chaque élève. Une entrée tardive ou une interruption peut modifier la trajectoire.'),
      question('EDU-SEI', 1, 'STRUCTURE', 'Quel examen correspond à la fin du premier cycle secondaire ?', ['BEPC', 'CEPE', 'Licence'], 'Le premier cycle va de la 6e à la 3e : BEPC. Le CEPE correspond au primaire ; la licence appartient au supérieur.'),
      b.recap(['Situer une classe dans son cycle.', 'Primaire : 6 ans ; secondaire : 4 puis 3 ans.', 'CEPE, BEPC et baccalauréat jalonnent le parcours.']),
    ]),
    lecon('EDU-SEI-L2', 'Rendre la scolarisation effective', 3, [
      b.texte('Nous allons distinguer une règle de scolarisation et les conditions de sa réalisation. Une inscription ne garantit pas à elle seule une scolarité suivie.'),
      b.retenir('La loi n° 2015-635 du 17 septembre 2015 a instauré la scolarisation obligatoire des enfants des deux sexes de **6 à 16 ans**. C’est un repère du système éducatif ivoirien.'),
      b.texte('L’**accès** est la possibilité d’entrer à l’école. Le **maintien** est la poursuite de la scolarité. L’**assiduité** est la présence régulière. Le **décrochage** est un processus de désengagement pouvant conduire à sortir de formation.'),
      b.exemple('Inscrit, mais souvent absent', 'Un enfant manque l’école à cause de la distance. Connaître son inscription ne suffit pas : il faut examiner cet obstacle et suivre sa présence.'),
      b.exemple('Une réponse coordonnée', 'L’établissement échange avec l’élève et la famille et mobilise les dispositifs disponibles. Les autorités et partenaires agissent aussi sur l’offre de places, l’accueil et les obstacles matériels.'),
      b.piege('L’obligation ne rend pas automatiquement réels l’accès, les apprentissages ou la sécurité. Accuser d’emblée l’élève peut masquer un obstacle que l’école peut aider à résoudre.'),
      question('EDU-SEI', 2, 'OBLIGATOIRE', 'Un élève inscrit ne vient presque plus. Que faut-il examiner ?', ['L’assiduité et les obstacles à la présence', 'Uniquement le total initial des inscrits', 'Uniquement la couleur de l’uniforme'], 'L’inscription indique une entrée administrative. L’assiduité renseigne sur la scolarité effective ; les obstacles expliquent ce qui peut l’empêcher.'),
      b.recap(['Repère légal : 6–16 ans, loi de 2015.', 'Accès, présence et maintien se complètent.', 'Rechercher les obstacles et coordonner la réponse.']),
    ]),
    lecon('EDU-SEI-L3', 'Identifier les acteurs de l’école', 3, [
      b.texte('Nous allons attribuer les rôles pour savoir à qui adresser une question. La **gouvernance scolaire** organise les responsabilités et décisions relatives à l’école.'),
      b.texte('Le ministère chargé de l’éducation définit les orientations nationales et ses services territoriaux assurent les relais. Le chef d’établissement organise le fonctionnement local dans le cadre applicable.'),
      b.tableau(['Acteur', 'Contribution'], [['Enseignant', 'Organiser et évaluer les apprentissages disciplinaires'], ['Éducateur', 'Accompagner la vie scolaire et le suivi des élèves'], ['Familles et élèves', 'Participer au dialogue et au suivi du parcours']]),
      b.texte('Le **COGES**, comité de gestion des établissements scolaires, associe des acteurs et partenaires de l’école. Il contribue à mobiliser la communauté autour de son fonctionnement et de la réussite scolaire.'),
      b.exemple('Des absences répétées', 'L’éducateur recueille les faits ; les enseignants apportent les observations utiles ; la famille aide à comprendre les obstacles ; la direction coordonne les décisions de sa compétence.'),
      b.piege('Participer ne donne pas toutes les compétences : un COGES ne remplace pas l’enseignant pour attribuer une note disciplinaire.'),
      question('EDU-SEI', 3, 'GOUVERNANCE', 'Qui évalue normalement les acquis dans une discipline ?', ['L’enseignant concerné', 'Le COGES seul', 'Le délégué seul'], 'L’évaluation disciplinaire relève de la mission pédagogique de l’enseignant. Les autres acteurs contribuent au suivi sans s’y substituer.'),
      b.recap(['Identifier les responsabilités.', 'Le COGES soutient la participation communautaire.', 'Coopérer en respectant les missions.']),
    ]),
    lecon('EDU-SEI-L4', 'Suivre un élève à partir de faits', 4, [
      b.texte('La **vie scolaire** concerne notamment la présence, les relations, la sécurité et la participation à l’établissement. Nous allons construire un suivi utile au parcours de l’élève.'),
      b.texte('Une **observation** décrit un fait vérifiable ; une **interprétation** propose une explication. « Trois retards cette semaine » décrit un fait. « Il méprise l’école » est une interprétation à vérifier.'),
      b.exemple('Un changement récent', 'Un élève ponctuel s’endort désormais en classe. L’éducateur note les faits, l’écoute discrètement et recherche les difficultés possibles avant de décider de la suite avec les personnes compétentes.'),
      b.liste(['Repérer les faits et leur évolution.', 'Écouter sans humiliation ni accusation.', 'Croiser les informations utiles avec les acteurs concernés.', 'Fixer une action concrète et une date de suivi.'], true),
      b.exemple('Un objectif observable', '« Vérifier l’arrivée chaque matin pendant deux semaines, puis faire le point » permet d’observer un changement. « Sois sérieux » ne précise ni action ni critère.'),
      b.piege('La discrétion n’est pas un secret absolu. Une information nécessaire à la protection se transmet aux personnes compétentes, en limitant sa diffusion.'),
      question('EDU-SEI', 4, 'VIE-SCOLAIRE', 'Quelle phrase décrit un fait ?', ['Absent les deux derniers lundis', 'Paresseux par nature', 'Incapable d’apprendre'], 'La présence est vérifiable dans le registre. Les autres formulations étiquettent la personne et ne constituent pas une observation utile.'),
      b.recap(['Observer avant d’interpréter.', 'Écouter et coordonner.', 'Agir puis vérifier l’effet de l’aide.']),
    ]),
    lecon('EDU-SEI-L5', 'Poser un cadre qui protège', 4, [
      b.texte('Nous allons comprendre la fonction éducative d’une règle. Le **règlement intérieur** explicite des droits, des devoirs et les procédures de l’établissement.'),
      b.texte('Une **sanction éducative** répond à un acte établi. Elle doit rester respectueuse, proportionnée et conforme au cadre applicable, avec l’intervention de l’autorité compétente.'),
      b.exemple('Un matériel dégradé', 'On établit les faits et on écoute l’élève. Une réparation adaptée et autorisée peut aider à comprendre les conséquences. Insulter publiquement ne fait comprendre ni la règle ni la réparation.'),
      b.retenir('Dialoguer ne supprime pas la responsabilité. L’adulte explique la règle, entend les faits et décide ou propose une réponse dans les limites de sa fonction.'),
      b.exemple('Une violence en cours', 'Protéger les personnes par une intervention adaptée et alerter les responsables est prioritaire. L’analyse des causes et les suites éducatives viennent après la sécurisation.'),
      b.piege('Une violence répétée ou une emprise n’est pas un désaccord entre personnes de force égale. La médiation ne remplace ni la protection ni les procédures de signalement.'),
      question('EDU-SEI', 5, 'CADRE', 'Une agression est en cours. Quelle priorité ?', ['Protéger et alerter selon le cadre applicable', 'Attendre le conseil de classe', 'Faire débattre publiquement de la victime'], 'Le danger immédiat exige une protection et un relais compétent. La discussion éducative ne peut précéder la mise en sécurité.'),
      b.recap(['La règle organise la sécurité commune.', 'La réponse vise un acte, dans le respect de la dignité.', 'Protéger avant d’analyser une urgence.']),
    ]),
    lecon('EDU-SEI-L6', 'Orienter vers des parcours de formation', 4, [
      b.texte('L’**orientation** accompagne un choix de parcours en tenant compte des intérêts, acquis et possibilités de formation. Nous allons distinguer les voies sans les hiérarchiser par des stéréotypes.'),
      b.texte('L’enseignement **général** apporte une formation large ; l’enseignement **technique** étudie notamment des domaines technologiques ; la formation **professionnelle** prépare des compétences liées à des métiers. Les articulations et conditions d’accès varient selon les filières.'),
      b.exemple('Un projet dans l’électricité', 'Il faut vérifier les formations, prérequis, coûts, certifications et possibilités de poursuite. L’éducateur facilite le dialogue avec les services compétents sans promettre un emploi.'),
      b.texte('L’**insertion professionnelle** est l’entrée et la stabilisation dans une activité de travail. Compétences, stages encadrés et liens avec les entreprises peuvent la faciliter ; les débouchés dépendent aussi de l’économie.'),
      b.exemple('Une faible participation', 'Image dévalorisée, manque d’information, distance ou coût peuvent limiter les candidatures. Ce sont des hypothèses à documenter ; elles n’autorisent pas à conclure que les élèves manquent de volonté.'),
      b.piege('Réserver une voie aux « mauvais élèves » entretient un stéréotype. Décrire plutôt ses exigences, ses compétences et ses perspectives vérifiées.'),
      question('EDU-SEI', 6, 'ORIENTATION', 'Quelle information aide un choix éclairé ?', ['Conditions d’accès et compétences préparées, avec perspectives vérifiées', 'Emploi garanti par une promesse', 'Prestige supposé du nom uniquement'], 'Un choix raisonné compare le contenu, l’accès et les perspectives. La promesse ne remplace pas une information vérifiable.'),
      b.recap(['Informer et accompagner un projet.', 'Distinguer les voies de formation.', 'Relier compétences et insertion sans garantie automatique.']),
    ]),
    lecon('EDU-SEI-L7', 'Construire une réponse sur un enjeu éducatif', 4, [
      b.texte('Nous allons transformer des connaissances en réponse de concours. Une **argumentation** relie une idée, un mécanisme et un exemple ; elle ne se limite pas à une liste de slogans.'),
      b.texte('Définir les mots et repérer la demande : expliquer des causes, montrer des enjeux et proposer des actions sont des tâches différentes. Distinguer ensuite faits du document, connaissances établies et hypothèses.'),
      b.exemple('Un obstacle d’information', 'Cause possible : les élèves connaissent mal une filière. Mécanisme : ils ne candidatent pas. Action : rencontres d’orientation. Indicateur : évolution des candidatures et de leur diversité après l’action.'),
      b.liste(['Définir le problème et les personnes concernées.', 'Expliquer les causes sans affirmer sans preuve.', 'Relier les actions aux causes et nommer les acteurs.', 'Préciser limites et indicateurs d’évaluation.'], true),
      b.exemple('Construire un centre', 'Cela augmente l’offre de places, mais l’effet dépend de l’accès, des équipements, des formateurs et des débouchés. Le nombre de bâtiments seul ne mesure pas la réussite des parcours.'),
      b.piege('Ne pas inventer un chiffre ou une loi. Un pourcentage donné dans un sujet s’attribue au document ; il ne devient pas une statistique actuelle pour toutes les années.'),
      question('EDU-SEI', 7, 'ANALYSE', 'Quelle proposition explique un mécanisme ?', ['Informer sur l’accès peut réduire l’autocensure et favoriser les candidatures', 'L’école est importante', 'Il faut tout améliorer immédiatement'], 'La première relie une action à un obstacle puis à un effet attendu. Les autres énoncent une valeur ou une intention sans expliquer comment agir.'),
      b.recap(['Définir, expliquer, illustrer.', 'Relier problème, acteurs et actions.', 'Attribuer les chiffres et reconnaître les limites.']),
    ]),
  ],
  exercices: [
    ordre({ ...edu(1, 1, ['STRUCTURE'], 'Situer les cycles', 'Repérer les étapes du parcours général avant de situer une classe. Les durées habituelles ne fixent pas un âge unique pour tous les élèves.', 'Partir du début du parcours.'), consigne: 'Ordonne les cycles de l’enseignement général.', mode: 'exact', elements: ['Préscolaire', 'Primaire', 'Secondaire premier cycle', 'Secondaire second cycle'], explication: 'Le préscolaire précède le primaire. Après le CM2 vient le premier cycle du secondaire, de la 6e à la 3e. Le second cycle conduit de la seconde à la terminale. Les interruptions éventuelles ne changent pas cet ordre institutionnel.' }),
    relier({ ...edu(2, 1, ['STRUCTURE'], 'Classe et diplôme', 'Identifier la classe qui clôt le cycle, puis son examen repère. Ne pas confondre secondaire et supérieur.', 'Relier la fin de cycle au diplôme.'), consigne: 'Associe chaque classe à son examen repère.', paires: [['CM2', 'CEPE'], ['3e', 'BEPC'], ['Terminale', 'Baccalauréat']], intrus: ['Licence'], explication: 'Le CM2 clôt le primaire : CEPE. La 3e clôt le premier cycle secondaire : BEPC. La terminale clôt le second cycle : baccalauréat. La licence appartient au supérieur et reste l’intrus.' }),
    qcm({ ...edu(3, 1, ['OBLIGATOIRE'], 'Lire une règle scolaire', 'Identifier le public concerné et la nature de l’obligation. Distinguer une obligation légale et les conditions de sa mise en œuvre.', 'Préciser le champ du texte.'), consigne: 'Quelle tranche d’âge est visée par la scolarisation obligatoire instaurée en 2015 en Côte d’Ivoire ?', options: ['6 à 16 ans', '3 à 10 ans', '12 à 21 ans'], bonne: 0, explication: 'La loi n° 2015-635 du 17 septembre 2015 a instauré l’obligation pour les enfants des deux sexes de 6 à 16 ans. L’existence du préscolaire ne modifie pas la tranche de ce repère légal.' }),
    relier({ ...edu(4, 1, ['GOUVERNANCE'], 'Des acteurs complémentaires', 'Attribuer chaque tâche à la fonction concernée. La coopération ne supprime pas les responsabilités professionnelles.', 'Identifier la mission principale.'), consigne: 'Associe acteur et contribution.', paires: [['Enseignant', 'Évaluer les acquis de sa discipline'], ['Éducateur', 'Suivre l’assiduité et la vie scolaire'], ['COGES', 'Mobiliser les acteurs et partenaires de l’école']], explication: 'L’enseignant évalue les apprentissages disciplinaires. L’éducateur accompagne notamment la présence et la vie scolaire. Le COGES favorise la participation des partenaires ; il ne remplace pas la notation disciplinaire.' }),
    classer({ ...edu(5, 2, ['VIE-SCOLAIRE'], 'Faits et interprétations', 'Un fait est décrit et vérifiable. Une interprétation propose une cause ou un jugement à confronter à des informations.', 'Décrire sans étiqueter.'), consigne: 'Classe les formulations.', categories: ['Fait observable', 'Interprétation ou jugement'], cartes: [['Trois retards notés cette semaine', 0], ['Il n’a aucune volonté', 1], ['Deux devoirs non rendus aux dates prévues', 0], ['Il cherche forcément à provoquer', 1]], explication: 'Retards et devoirs manquants peuvent être datés et vérifiés. L’absence de volonté et l’intention de provoquer sont des jugements sur la personne. Les faits donnés ne prouvent pas ces intentions ; il faut écouter et rechercher les obstacles.' }),
    ordre({ ...edu(6, 2, ['VIE-SCOLAIRE', 'OBLIGATOIRE'], 'Un suivi vérifiable', 'Hors urgence, partir d’un constat, comprendre les obstacles, agir puis faire le point. Un objectif doit permettre d’observer un changement.', 'Constat → compréhension → action → bilan.'), consigne: 'Sans danger immédiat signalé, ordonne le suivi d’absences répétées.', mode: 'exact', elements: ['Vérifier les dates d’absence', 'Écouter et rechercher les obstacles avec les acteurs utiles', 'Convenir d’une aide et d’un objectif observable', 'Faire le point à la date prévue'], explication: 'Vérifier évite de partir d’une rumeur. L’entretien recherche les obstacles avant de choisir une aide. L’objectif concret et le bilan permettent ensuite d’évaluer la présence et d’ajuster l’accompagnement.' }),
    entourer({ ...edu(7, 2, ['CADRE'], 'Répondre à un acte', 'Une réponse éducative se fonde sur les faits et le cadre applicable. Elle respecte la dignité et les compétences de l’autorité qui décide.', 'Faits, proportion et procédure.'), consigne: 'Sélectionne les éléments d’une réponse éducative appropriée.', elements: [['Expliquer la règle', true], ['Entendre les faits et les explications', true], ['Respecter l’autorité compétente', true], ['Humilier publiquement', false], ['Proportionner la réponse à l’acte', true]], explication: 'La règle expliquée rend l’attente compréhensible. L’écoute aide à établir les faits. La compétence et la proportion évitent l’arbitraire. L’humiliation vise la personne et dégrade la relation au lieu d’aider à comprendre l’acte.' }),
    vf({ ...edu(8, 2, ['CADRE'], 'Discrétion et protection', 'Écouter dans un cadre discret puis mobiliser les personnes compétentes si la sécurité l’exige. Limiter la diffusion aux informations nécessaires.', 'Ne pas promettre un secret empêchant la protection.'), consigne: 'Un élève signale des violences répétées. Juge ces propositions.', affirmations: [['L’écouter discrètement est approprié.', true], ['Il faut toujours promettre de ne prévenir personne, même en danger.', false], ['Mobiliser les responsables selon les procédures est nécessaire.', true]], explication: 'L’écoute discrète limite l’exposition. Un secret absolu pourrait empêcher de protéger : il faut en expliquer les limites. Le relais compétent permet une réponse adaptée ; il n’autorise pas à diffuser le récit à toute la communauté.' }),
    glisser({ ...edu(9, 2, ['ORIENTATION'], 'Parcours et travail', 'Distinguer le choix de formation, l’acquisition de compétences et l’accès au travail. Ces étapes se soutiennent sans se confondre.', 'Accompagner un parcours.'), consigne: 'Complète les notions.', texte: 'Accompagner un choix de parcours relève de l’{{orientation}}. Préparer des compétences de métier relève de la formation {{professionnelle}}. Entrer dans le travail relève de l’{{insertion}}.', distracteurs: ['exclusion', 'notation'], explication: 'L’orientation éclaire le choix ; la formation professionnelle prépare des compétences liées au métier ; l’insertion concerne l’accès et la stabilisation dans le travail. Une formation ne garantit pas automatiquement un poste.' }),
    qcm({ ...edu(10, 3, ['ORIENTATION', 'ANALYSE'], 'Relier cause et action', 'Une proposition utile répond à un obstacle identifié. Expliquer le mécanisme attendu puis vérifier que cet obstacle existe dans la situation étudiée.', 'Cause → action → effet attendu.'), source: annale2026, consigne: 'Adaptation de la question ENS 2026 sur la faible participation à l’enseignement technique : quel argument est construit ?', options: ['Un manque d’information peut limiter les candidatures ; des rencontres sur les filières peuvent éclairer les choix', 'Tous les élèves évitent ces voies par paresse', 'Changer un nom garantit seul l’emploi à tous'], bonne: 0, explication: '(ENS Éducateur 2026, Psychopédagogie, question 1 — adaptation) La question demande des explications. L’information insuffisante est une hypothèse : une possibilité inconnue ne sera pas choisie. Une rencontre peut agir sur cet obstacle, à vérifier localement. Le jugement de paresse ne repose sur aucune preuve ; la garantie d’emploi est injustifiée.' }),
    qcm({ ...edu(11, 3, ['ORIENTATION', 'ANALYSE'], 'Formation et insertion', 'Expliquer le lien entre compétences, besoins productifs et débouchés. Reconnaître que la formation agit avec d’autres conditions économiques.', 'Un effet conditionnel à expliquer.'), source: annale2026, consigne: 'Adaptation de la question ENS 2026 sur l’intérêt de la formation technique : quelle analyse est défendable ?', options: ['Compétences adaptées et liens avec les entreprises peuvent faciliter l’insertion si des débouchés existent', 'La formation technique supprime tout chômage immédiatement', 'L’enseignement général n’apporte aucune compétence'], bonne: 0, explication: '(ENS Éducateur 2026, Psychopédagogie, question 2 — adaptation) La formation technique peut rapprocher compétences et besoins productifs. L’effet suppose notamment formateurs, équipements et liens professionnels de qualité. L’emploi dépend aussi de la demande économique : pas de garantie universelle, ni de raison de dévaloriser l’enseignement général.' }),
    qcm({ ...edu(12, 3, ['ANALYSE'], 'Mesurer le résultat visé', 'Distinguer moyens, activités et résultats. Choisir un indicateur correspondant à l’objectif et à une échéance précise.', 'Évaluer ce que l’on veut améliorer.'), consigne: 'Un projet veut améliorer l’insertion des diplômés. Quel suivi est le plus utile ?', options: ['Leurs situations d’emploi et de poursuite d’études à échéance définie, selon les formations', 'Seulement le nombre d’affiches produites', 'Compter chaque inscription comme un emploi'], bonne: 0, explication: 'L’objectif concerne les parcours après formation : il faut les suivre à une date définie et selon les filières. Les affiches mesurent un moyen de communication. L’inscription ne mesure pas l’emploi. Le contexte économique doit aussi être examiné pour interpréter les résultats.' }),
  ],
};

const ps = (...args) => ({ ...fiche('ENS-EDU-PSYCHOPEDA', ...args), source: { type: 'original', inspireDe: 'ENS Éducateur : préparation psychopédagogique, complément au sujet 2026' } });
